namespace sv_e6978fa77b114746bd1e7b70a2e3428d.Services;

public class WarehouseState
{
    private string _selectedWarehouseId = "WH-001";

    public string SelectedWarehouseId => _selectedWarehouseId;

    public string SelectedWarehouseName =>
        Warehouses.FirstOrDefault(w => w.Id == _selectedWarehouseId)?.Name ?? "Unknown";

    public IReadOnlyList<Warehouse> Warehouses { get; } =
    [
        new("WH-001", "Warehouse A — Main Distribution"),
        new("WH-002", "Warehouse B — Regional South"),
        new("WH-003", "Warehouse C — Cold Storage"),
        new("WH-004", "Warehouse D — Overflow")
    ];

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_selectedWarehouseId == warehouseId) return;
        _selectedWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

public record Warehouse(string Id, string Name);

namespace sv_e6978fa77b114746bd1e7b70a2e3428d.Services;

public class InventoryAlertService : IDisposable
{
    private readonly WarehouseState _warehouseState;
    private Timer? _timer;
    private int _subscriberCount;
    private readonly Lock _lock = new();

    public int CurrentLowStockCount { get; private set; }

    /// <summary>
    /// Fired when polling detects a new alert count. All subscribers
    /// are notified regardless of which component triggered the poll.
    /// </summary>
    public event Func<Task>? OnAlertCountChanged;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += HandleWarehouseChanged;
    }

    /// <summary>
    /// Simulates a database query returning low-stock item count.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = Random.Shared.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Call when a component wants polling to be active.
    /// Polling starts on first subscriber, stops when all unsubscribe.
    /// </summary>
    public void StartPolling()
    {
        lock (_lock)
        {
            _subscriberCount++;
            if (_subscriberCount == 1)
            {
                _timer = new Timer(PollCallback, null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
            }
        }
    }

    public void StopPolling()
    {
        lock (_lock)
        {
            _subscriberCount = Math.Max(0, _subscriberCount - 1);
            if (_subscriberCount == 0)
            {
                _timer?.Dispose();
                _timer = null;
            }
        }
    }

    private async void PollCallback(object? state)
    {
        var count = await GetLowStockCountAsync(_warehouseState.SelectedWarehouseId);
        CurrentLowStockCount = count;
        await NotifySubscribers();
    }

    private async void HandleWarehouseChanged()
    {
        // Immediately re-poll when the warehouse changes
        var count = await GetLowStockCountAsync(_warehouseState.SelectedWarehouseId);
        CurrentLowStockCount = count;
        await NotifySubscribers();
    }

    private async Task NotifySubscribers()
    {
        if (OnAlertCountChanged is not null)
        {
            await OnAlertCountChanged.Invoke();
        }
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= HandleWarehouseChanged;
        _timer?.Dispose();
    }
}

