+    private async void HandleWarehouseChanged()
+    {
+        var count = await GetLowStockCountAsync(_warehouseState.SelectedWarehouseId);
+        CurrentLowStockCount = count;
+        await NotifySubscribers();
+    }
+
+    private async Task NotifySubscribers()
+    {
+        if (OnAlertCountChanged is not null)
+        {
+            await OnAlertCountChanged.Invoke();
+        }
+    }
+
