@inject sv_e6978fa77b114746bd1e7b70a2e3428d.Services.InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-header">
        <strong>@WarehouseState.SelectedWarehouseName</strong>
    </div>
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="display-4 text-danger">@AlertService.CurrentLowStockCount</p>
        <p class="text-muted">
            Items below minimum stock level. Polling every 10 seconds.
        </p>
    </div>
</div>

<div class="alert alert-info">
    <strong>How it works:</strong> This page starts polling when you navigate here and stops
    when you leave. The sidebar badge and this page both update simultaneously because they
    subscribe to the same <code>InventoryAlertService.OnAlertCountChanged</code> event.
    Each user session has its own scoped service instances, so warehouse selections are independent.
</div>

@code {
    private Func<Task>? _alertHandler;
    private Action? _warehouseHandler;

    protected override void OnInitialized()
    {
        // Subscribe to alert changes (fires from timer — use InvokeAsync)
        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _alertHandler;

        // Subscribe to warehouse changes (fires from Blazor sync context)
        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        WarehouseState.OnChange += _warehouseHandler;

        // Start polling — this is the "dashboard is visible" trigger
        AlertService.StartPolling();
    }

    public void Dispose()
    {
        AlertService.StopPolling();

        if (_alertHandler is not null)
            AlertService.OnAlertCountChanged -= _alertHandler;

        if (_warehouseHandler is not null)
            WarehouseState.OnChange -= _warehouseHandler;
    }
}

